mapper.select:
SELECT u.id,
       u.name,
       u.email,
       u.created_at,
       o.id                AS order_id,
       o.customer_name,
       o.customer_email,
       o.customer_phone,
       o.shipping_address,
       o.status,
       o.total_amount,
       ec.contact_name,
       ec.contact_phone,
       ec.relation,
       pm.card_holder_name,
       pm.card_number_masked,
       u.name || ' (' || u.email || ')' AS search_result_label
FROM users u
         LEFT JOIN orders o ON o.user_id = u.id
         LEFT JOIN emergency_contacts ec ON ec.user_id = u.id
         LEFT JOIN payment_methods pm ON pm.user_id = u.id



            AND u.email = #{email}


            AND o.customer_email = #{orderEmail}
            AND o.customer_phone = #{orderPhone}


            AND ec.contact_name = #{contactName}
            AND ec.contact_phone = #{contactPhone}


            AND pm.card_holder_name = #{cardHolderName}


            AND u.name ILIKE #{namePattern}



        AND o.total_amount >= #{minSpend}


        AND o.total_amount <= #{maxSpend}


        AND o.shipping_address LIKE #{shippingAddressLike}


        AND ec.relation = #{relation}


        AND o.status IN

            #{status}



        AND u.id IN

            #{uid}



ORDER BY u.id
